<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Certificate - {{ $student->user->name }}</title><style>*{box-sizing:border-box}body{margin:0;background:#eef2f7;font-family:Georgia,'Times New Roman',serif;color:#172033}.actions{text-align:center;padding:16px}.actions button{border:0;border-radius:7px;background:#173f7a;color:white;padding:11px 26px;font-size:15px;cursor:pointer}.certificate{width:210mm;min-height:297mm;margin:0 auto;background:white;padding:12mm}.border1{min-height:273mm;border:5px solid #173f7a;padding:6px}.border2{min-height:269mm;border:2px solid #d3a328;padding:15mm 16mm;position:relative}.top{text-align:center}.logo{width:82px;height:82px;object-fit:contain}.school{font-size:31px;font-weight:bold;color:#173f7a}.address{font-family:Arial,sans-serif;font-size:13px;margin-top:5px}.rule{height:3px;background:#d3a328;margin:14px 0}.cert-title{text-align:center;font-size:28px;text-transform:uppercase;letter-spacing:2px;text-decoration:underline;color:#173f7a;margin:24px 0 28px}.body{font-size:18px;line-height:1.9;text-align:justify}.name{font-weight:bold;text-transform:uppercase;border-bottom:1px dotted #555;padding:0 8px}.details{margin:22px 0;border-collapse:collapse;width:100%;font-family:Arial,sans-serif;font-size:14px}.details td{padding:7px;border-bottom:1px solid #ddd}.details td:first-child{font-weight:bold;width:34%}.footer{display:flex;justify-content:space-between;align-items:flex-end;margin-top:58px}.date{font-family:Arial,sans-serif;font-size:14px}.signature{text-align:center;width:210px;font-family:Arial,sans-serif}.signature-line{border-top:1px solid #333;padding-top:7px;font-weight:bold}.seal{position:absolute;bottom:65px;left:50%;transform:translateX(-50%);width:90px;height:90px;border:2px dashed #9aa8bb;border-radius:50%;display:flex;align-items:center;justify-content:center;text-align:center;color:#7d8999;font-family:Arial,sans-serif;font-size:12px}@media print{@page{size:A4 portrait;margin:0}.actions{display:none}body{background:#fff}.certificate{margin:0}}</style></head><body><div class="actions"><button onclick="window.print()">Print / Save as PDF</button></div><div class="certificate"><div class="border1"><div class="border2"><div class="top"><img src="{{ asset('images/logo.png') }}" class="logo"><div class="school">{{ $school?->school_name ?: 'C-Net Pathshala' }}</div>@if($school?->address)<div class="address">{{ $school->address }}</div>@endif</div><div class="rule"></div>@php($title=$type==='bonafide'?'Bonafide Certificate':($type==='character'?'Character Certificate':'Study Certificate'))<div class="cert-title">{{ $title }}</div><div class="body">This is to certify that <span class="name">{{ $student->user->name }}</span>@if($student->father_name), son/daughter of <strong>{{ $student->father_name }}</strong>@endif, Admission No. <strong>{{ $student->admission_no }}</strong>, is a bona fide student of <strong>{{ $school?->school_name ?: 'C-Net Pathshala' }}</strong>@if($student->class_name), studying in Class <strong>{{ $student->class_name }}</strong>@if($student->section), Section <strong>{{ $student->section }}</strong>@endif @endif.@if($type==='character') During the period of study, the student's conduct and character have been found to be good.@elseif($type==='study') This certificate is issued as proof of the student's study and enrolment in this institution.@else This certificate is issued on the basis of the school records.@endif @if($purpose) The certificate is issued for the purpose of <strong>{{ $purpose }}</strong>.@endif</div><table class="details"><tr><td>Student Name</td><td>{{ $student->user->name }}</td></tr><tr><td>Father's Name</td><td>{{ $student->father_name ?: '—' }}</td></tr><tr><td>Mother's Name</td><td>{{ $student->mother_name ?: '—' }}</td></tr><tr><td>Admission No.</td><td>{{ $student->admission_no }}</td></tr><tr><td>Class / Section</td><td>{{ $student->class_name ?: '—' }}{{ $student->section?' / '.$student->section:'' }}</td></tr><tr><td>Roll No.</td><td>{{ $student->roll_no ?: '—' }}</td></tr>@if($student->date_of_birth)<tr><td>Date of Birth</td><td>{{ $student->date_of_birth->format('d-m-Y') }}</td></tr>@endif</table><div class="seal">SCHOOL<br>SEAL</div><div class="footer"><div class="date">Date: {{ now()->format('d-m-Y') }}</div><div class="signature"><div style="height:55px"></div><div class="signature-line">Authorized Signature</div></div></div></div></div></div></body></html>